"""Real JEE Main questions — Chemistry Unit 14: Some Basic Principles of Organic Chemistry. Our own solutions; chk
recomputes what can be computed — isomer counts by building carbon trees, chiral centres and stereoisomers from
the structure (orgkit.py), distinct hydrogen environments for substitution products, aromaticity by Hückel's
4n + 2 count, masses from formulae — and checks orders against tables of pKa, carbocation/carbanion stability and
nucleophilicity written from NCERT. Naming and statement items are checked against a fact table."""
from common import new_registry, pick, verify
from chemkit import stmt, pickset, letters
from orgkit import Mol, alkanes, ring_patterns, ring_h_sites
P, add = new_registry()
STO = ['Both Statement I and Statement II are true', 'Both Statement I and Statement II are false', 'Statement I is true but Statement II is false', 'Statement I is false but Statement II is true']
STC = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct']
def order(keys, val, desc=True): return sorted(keys, key=lambda k: -val[k] if desc else val[k])
def huckel(pi, cyclic_conj=True, planar=True): return cyclic_conj and planar and pi % 4 == 2
# pKa (approx., water) used for acidity orders
PKA = {'HCOOH': 3.75, 'CH3COOH': 4.76, 'CH3CH2COOH': 4.87, 'CH3CH2CH2COOH': 4.82 + 0.1, 'PhSO3H': -2.8, 'EtCOOH': 4.87, '3-EtO-phenol': 9.4, 'HC≡C–CO2Et': 25}
PKAH = {'piperidine': 11.1, 'pyridine': 5.2, 'pyrrole': -3.8}   # pKa of the conjugate acid → basicity

