add(('2026', 'Jan', '2026-01-22', 2), 'nom', 'The IUPAC name of the following compound is : CH_{3}CH_{2}–CH(CH_{3})–CH_{2}CH_{2}–CH(Br)–COO–CH_{2}CH_{2}CH_{3}', ['n-propyl-1-bromo-4-methylhexanoate', 'n-propyl-2-bromo-5-methylheptanoate', '2-bromo-5-methylpropanoate', '2-bromo-5-methylhexylpropanoate'], 2,
    lambda: pick(['a', 'b', 'c', 'd'], 'b'), ['Acid part: C(=O) is C-1 of a 7-carbon chain (heptanoate) with Br at 2 and CH_{3} at 5.', 'Alkyl part: n-propyl → propyl 2-bromo-5-methylheptanoate.'], 'nom', 1)

# ---------------- reaction types, nucleophiles, mechanisms ----------------
add(('2024', 'Feb', '2024-02-01', 1), 'mech', 'Ionic reactions with organic compounds proceed through: (A) Homolytic bond cleavage (B) Heterolytic bond cleavage (C) Free radical formation (D) Primary free radical (E) Secondary free radical', ['(A) only', '(C) only', '(B) only', '(D) and (E) only'], 3,
    lambda: pickset(['(A) only', '(C) only', '(B) only', '(D) and (E) only'], dict(A=False, B=True, C=False, D=False, E=False)), ['Ions come from heterolysis (the bond pair goes to one atom). Homolysis gives radicals.'], 'mech', 1)
add(('2024', 'Apr', '2024-04-04', 1), 'mech', 'Which among the following is incorrect statement ?', ['Electromeric effect dominates over inductive effect', 'The electromeric effect is, temporary effect', 'The organic compound shows electromeric effect in the presence of the reagent only', 'Hydrogen ion (H^{+}) shows negative electromeric effect'], 4,
    lambda: pick([True, True, True, False], False), ['When H^{+} attacks, the π electrons move towards the atom it bonds to: that is a +E effect.', 'The other three describe the electromeric effect correctly.'], 'mech', 1)
